def solve_dp(target, choices):
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for i in range(1, target + 1):
        for choice in choices:
            if i - choice >= 0:
                dp[i] = min(dp[i], dp[i - choice] + 1)

    return dp[target] if dp[target] != float('inf') else -1

